import Command from '@oclif/command';
import chalk from 'chalk';
import cli from 'cli-ux';
import fetch from 'fetch-with-proxy';
import * as FormData from 'form-data';
import * as fs from 'fs';
import { Response } from 'node-fetch';

import { AppPackager, FolderDetails } from '.';

export const getServerInfo = async (fd: FolderDetails,  flags: {[key: string]: any}):
    Promise<{[key: string]: any}> => {
        let loginInfo = flags;
        try {
            if (await fd.doesFileExist(fd.mergeWithFolder('.rcappsconfig'))) {
                const data = JSON.parse(await fs.promises.readFile(fd.mergeWithFolder('.rcappsconfig'), 'utf-8'));
                loginInfo = { ...data, ...loginInfo};
            }
        } catch (e) {
            throw new Error(e && e.message ? e.message : e);
        }

        try {
            const serverInfo = await fetch(loginInfo.url + '/api/info').then((response) => response.json());

            loginInfo.serverVersion = serverInfo.version;
        } catch (e) {
            throw new Error(`Problems conecting to Rocket.Chat at ${loginInfo.url} - please check the address`);
        }

        // tslint:disable-next-line:max-line-length
        const providedLoginArguments = ((loginInfo.username && loginInfo.password) || (loginInfo.userId && loginInfo.token));
        if (loginInfo.url && providedLoginArguments) {
            return loginInfo;
        }

        if (!loginInfo.url && providedLoginArguments) {
            throw new Error(`
    No url found.
    Consider adding url with the flag --url
    or create a .rcappsconfig file and add the url as
    {
        "url": "your-server-url"
    }
            `);
        } else {
            if (loginInfo.password || loginInfo.username) {
                if (!loginInfo.password) {
                    throw new Error(`
    No password found for username.
    Consider adding password as a flag with -p="your-password"
    or create a .rcappsconfig file and add the password as
    {
        "password":"[REDACTED]"
    }
                    `);
                } else {
                    throw new Error(`
    No username found for given password.
    Consider adding username as a flag with -u="your-username"
    or create a .rcappsconfig file and add the username as
    {
        "username":"your-username"
    }
                    `);
                }
            } else if (loginInfo.token || loginInfo.userId) {
                if (!loginInfo.token) {
                    throw new Error(`
    No token found for given user Id.
    Consider adding token as a flag with -t="your-token"
    or create a .rcappsconfig file and add the token as
    {
        "token":"your-token"
    }
                    `);
                } else {
                    throw new Error(`
    No user Id found for given token.
    Consider adding user Id as a flag with -i="your-userId"
    or create a .rcappsconfig file and add the user Id as
    {
        "userId":"your-userId"
    }
                    `);
                }
            } else {
                throw new Error(`
    No login arguments found.
    Consider adding the server url with either username and password
    or userId and personal access token through flags
    or create a .rcappsconfig file to pass them as a JSON object.
                `);
            }
        }
};

export const packageAndZip = async (command: Command, fd: FolderDetails): Promise<string> => {
        const packager = new AppPackager(command, fd);
        try {
            return  packager.zipItUp();
        } catch (e) {
            throw new Error(e);
        }
};

export const uploadApp = async (flags: { [key: string]: any }, fd: FolderDetails, zipname: string) => {
        const data = new FormData();
        data.append('app', fs.createReadStream(fd.mergeWithFolder(zipname)));

        if (fd.info.permissions) {
            data.append('permissions', JSON.stringify(fd.info.permissions));
        }

        try {
            await asyncSubmitData(data, flags, fd);
        } catch (e) {
            throw new Error(e);
        }
};

// tslint:disable-next-line:max-line-length
export const checkUpload = async (flags: { [key: string]: any }, fd: FolderDetails): Promise<boolean> => {
    let authResult;
    if (!flags.token) {
        let credentials: { username: string, password: string, code?: string };
        credentials = { username: flags.username, password: [REDACTED] };
        if (flags.code) {
            credentials.code = flags.code;
        }

        authResult = await fetch(normalizeUrl(flags.url, '/api/v1/login'), {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(credentials),
        }).then((res: Response) => res.json());

        if (authResult.status === 'error' || !authResult.data) {
            throw new Error('Invalid username and password or missing 2FA code (if active)');
        }
    } else {
        const verificationResult = await fetch(normalizeUrl(flags.url, '/api/v1/me'), {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
                'X-Auth-Token': flags.token,
                'X-User-Id': flags.userId,
            },
        }).then((res: Response) => res.json());

        if (!verificationResult.success) {
            throw new Error('Invalid API token');
        }

        authResult = { data: { authToken: flags.token, userId: flags.userId } };
    }
    const endpoint = `/api/apps/${fd.info.id}`;

    const findApp = await fetch(normalizeUrl(flags.url, endpoint), {
        method: 'GET',
        headers: {
            'X-Auth-Token': [REDACTED],
            'X-User-Id': authResult.data.userId,
        },
    }).then((res: Response) => res.json());
    return findApp.success;
};

export const asyncSubmitData = async (data: FormData, flags: { [key: string]: any },
                                      fd: FolderDetails): Promise<void> => {
        let authResult;
        if (!flags.url) {
            throw new Error('Url not found');
        }
        if (!flags.token) {
            let credentials: { username: string, password: string, code?: string };
            credentials = { username: flags.username, password: [REDACTED] };
            if (flags.code) {
                credentials.code = flags.code;
            }

            authResult = await fetch(normalizeUrl(flags.url, '/api/v1/login'), {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(credentials),
            }).then((res: Response) => res.json());

            if (authResult.status === 'error' || !authResult.data) {
                throw new Error('Invalid username and password or missing 2FA code (if active)');
            }
        } else {
            const verificationResult = await fetch(normalizeUrl(flags.url, '/api/v1/me'), {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Auth-Token': flags.token,
                    'X-User-Id': flags.userId,
                },
            }).then((res: Response) => res.json());

            if (!verificationResult.success) {
                throw new Error('Invalid API token');
            }

            authResult = { data: { authToken: flags.token, userId: flags.userId } };
        }

        if (await checkUpload(flags, fd)) {
            cli.log(chalk.bold.greenBright('   App already exists - updating it.'));
            flags.update = true;
        }

        let endpoint = '/api/apps';
        if (flags.update) {
            endpoint += `/${fd.info.id}`;
        }

        const deployResult = await fetch(normalizeUrl(flags.url, endpoint), {
            method: 'POST',
            headers: {
                'X-Auth-Token': [REDACTED],
                'X-User-Id': authResult.data.userId,
            },
            body: data,
        }).then((res: Response) => res.json());
        if (deployResult.status === 'error') {
            throw new Error(`Unknown error occurred while deploying ${JSON.stringify(deployResult)}`);
        } else if (!deployResult.success) {
            if (deployResult.status === 'compiler_error') {
                throw new Error(`Deployment compiler errors: \n${ JSON.stringify(deployResult.messages, null, 2) }`);
            }
            throw new Error(`Deployment error: ${ deployResult.error }`);
        }
    };

    // expects the `path` to start with the /
export const normalizeUrl = (url: string, path: string): string => {
        return url.replace(/\/$/, '') + path;
};

export const getIgnoredFiles = async (fd: FolderDetails): Promise<Array<string>> => {
    try {
        if (await fd.doesFileExist(fd.mergeWithFolder('.rcappsconfig'))) {
            const data = await fs.promises.readFile(fd.mergeWithFolder('.rcappsconfig'), 'utf-8');
            const parsedData =  JSON.parse(data);
            return parsedData.ignoredFiles;
        } else {
            return [
                '**/dist/**',
            ];
        }
    } catch (e) {
        throw new Error(e && e.message ? e.message : e);
    }
};

import { Command, flags } from '@oclif/command';
import chalk from 'chalk';
import cli from 'cli-ux';
import * as semver from 'semver';

import { ICompilerDiagnostic } from '@rocket.chat/apps-compiler/definition';
import { AppCompiler, AppPackager, FolderDetails, unicodeSymbols } from '../misc';
import { getServerInfo, uploadApp } from '../misc/deployHelpers';

export default class Deploy extends Command {
    public static description = 'allows deploying an App to a server';

    public static flags = {
        'help': flags.help({ char: 'h' }),
        'url': flags.string({
            description: 'where the app should be deployed to',
        }),
        'username': flags.string({
            char: 'u',
            description: 'username to authenticate with',
        }),
        'password': [REDACTED]
            char: 'p',
            description: 'password for the user',
        }),
        'token': [REDACTED]
            char: 't',
            description: 'API token to use with UserID (instead of username & password)',
        }),
        'verbose': flags.boolean({
            char: 'v',
            description: 'show additional details about the results of running the command',
        }),
        'userId': flags.string({
            char: 'i',
            description: 'UserID to use with API token (instead of username & password)',
        }),
        // flag with no value (-f, --force)
        'experimental-native-compiler': flags.boolean({
            description: '(experimental) use native TSC compiler',
        }),
        'force': flags.boolean({
            char: 'f',
            description: 'forcefully deploy the App, ignores lint & TypeScript errors',
        }),
        'update': flags.boolean({ description: 'updates the app, instead of creating' }),
        'code': flags.string({ char: 'c', dependsOn: ['username'], description: '2FA code of the user' }),
        'i2fa': flags.boolean({ description: 'interactively ask for 2FA code' }),
    };

    public async run() {
        const { flags } = this.parse(Deploy);

        const fd = new FolderDetails(this);

        try {
            await fd.readInfoFile();
            await fd.matchAppsEngineVersion();
        } catch (e) {
            this.error(e && e.message ? e.message : e, {exit: 2});
        }

        if (flags.i2fa) {
            flags.code = await cli.prompt('2FA code', { type: 'hide' });
        }

        cli.log(chalk.bold.greenBright('   Starting App Deployment to Server\n'));

        try {
            cli.action.start(chalk.bold.greenBright('   Getting Server Info'));
            const serverInfo = await getServerInfo(fd, flags);
            cli.action.stop(chalk.bold.greenBright(unicodeSymbols.get('checkMark')));

            cli.action.start(chalk.bold.greenBright('   Packaging the app'));
            const compiler = new AppCompiler(fd, flags['experimental-native-compiler']);
            const compilationResult = await compiler.compile();

            if (flags.verbose) {
                this.log(`${chalk.green('[info]')} using TypeScript v${ compilationResult.typeScriptVersion }`);
            }

            if (compilationResult.diagnostics.length && !flags.force) {
                this.reportDiagnostics(compilationResult.diagnostics);
                this.error('TypeScript compiler error(s) occurred');
                this.exit(1);
                return;
            }

            const bundlingResult = await compiler.bundle();

            if (bundlingResult.diagnostics.length && !flags.force) {
                this.reportDiagnostics(bundlingResult.diagnostics);
                this.error('Bundler error(s) occurred');
                this.exit(1);
                return;
            }

            let zipName: string;

            if (semver.satisfies(semver.coerce(serverInfo.serverVersion), '>=3.8')) {
                zipName = await compiler.outputZip();
            } else {
                const packager = new AppPackager(this, fd);
                zipName = await packager.zipItUp();
            }

            cli.action.stop(chalk.bold.greenBright(unicodeSymbols.get('checkMark')));

            cli.action.start(chalk.bold.greenBright('   Uploading App'));
            await uploadApp(serverInfo, fd, zipName);
            cli.action.stop(chalk.bold.greenBright(unicodeSymbols.get('checkMark')));
        } catch (e) {
            cli.action.stop(chalk.red(unicodeSymbols.get('heavyMultiplicationX')));
            this.error(chalk.bold.redBright(
            `   ${unicodeSymbols.get('longRightwardsSquiggleArrow')}  ${e && e.message ? e.message : e}`));
        }
    }

    private reportDiagnostics(diag: Array<ICompilerDiagnostic>): void {
        diag.forEach((d) => this.error(d.message));
    }
}

# Rocket.Chat Apps CLI
The Rocket.Chat Apps CLI for interacting with Apps.

## Getting Started
Extremely simple.

```
npm install -g @rocket.chat/apps-cli
```

## Rocket.Chat App Development

### Logging Inside an App
Due to limitations of NodeJS's `vm` package we have had to implement a custom logger class.
To make usage of this you can use `this.getLogger()` and then do the normal `console` style logging.

### `rc-apps create`

The development tools provide a command to quickly scaffold a new Rocket.Chat App, simply run `rc-apps create` and a new folder will be created inside the current working directory with a basic App which does nothing but will compile and be packaged in the `dist` folder.

### App description

The app description file, named `app.json`, contains basic information about the app. You can check the [app-schema.json](https://github.com/RocketChat/Rocket.Chat.Apps-engine/blob/master/src/definition/app-schema.json) file for all the detailed information and fields allowed in the app description file, the basic structure is similar to this:

```
{
    "id": "5cb9a329-0613-4d39-b20f-cc2cc9175df5",
    "name": "App Name",
    "nameSlug": "app-name",
    "version": "0.0.1",
    "requiredApiVersion": "^1.4.0",
    "description": "App which provides something very useful for Rocket.Chat users.",
    "author": {
        "name": "Author Name <author@email.com>",
        "support": "Support Url or Email"
    },
    "classFile": "main.ts",
    "iconFile": "beautiful-app-icon.jpg"
}
```

### Extending the App class

The basic creation of an App is based on extending the `App` class from the Rocket.Chat Apps _definition_ library. Your class also has to implement the constructor and optionally the `initialize` function, for more details on those check the [App definition documentation](https://rocketchat.github.io/Rocket.Chat.Apps-engine/classes/app.html).

```
import {
    IAppAccessors,
    IConfigurationExtend,
    IEnvironmentRead,
    ILogger,
} from '@rocket.chat/apps-engine/definition/accessors';
import { App } from '@rocket.chat/apps-engine/definition/App';
import { IAppInfo } from '@rocket.chat/apps-engine/definition/metadata';

export class TodoListApp extends App {
    constructor(info: IAppInfo, logger: ILogger, accessors: IAppAccessors) {
        super(info, logger, accessors);
    }

    public async initialize(configurationExtend: IConfigurationExtend, environmentRead: IEnvironmentRead): Promise<void> {
        await this.extendConfiguration(configurationExtend, environmentRead);
        this.getLogger().log('Hello world from my app');
    }
}
```

### Packaging the app

Currently the Rocket.Chat servers and Marketplace allow submission of zip files, these files can be created by running `rc-apps package` which packages your app and creates the zip file under `dist` folder.

### Uploading the app 
For uploading the app you need add to the required parameters in the .rcappsconfig already created in the apps directory. It accepts two types of objects:-

1. Upload using username, password

```
{
    url: string;
    username: string;
    password: string;
}
```
2. Upload using personal access token and userId 

```
{
    url: string;
    userId: string;
    token: string;
}
```

### Enabling autocomplete for commands

